const SUPPORTED_LANGS = [
  { code: 'en', name: 'English', flag: '🇦🇺' },
  { code: 'de', name: 'Deutsch', flag: '🇩🇪' },
  { code: 'fr', name: 'Français', flag: '🇫🇷' },
  { code: 'it', name: 'Italiano', flag: '🇮🇹' },
  { code: 'sv', name: 'Svenska', flag: '🇸🇪' },
  { code: 'ar', name: 'العربية', flag: '🇸🇦', rtl: true },
  { code: 'ta', name: 'தமிழ்', flag: '🇮🇳' },
  { code: 'si', name: 'සිංහල', flag: '🇱🇰' }
];

function applyTranslations(container) {
  const root = container || document;
  const lang = localStorage.getItem('juzly_lang') || 'en';
  const dict = I18N_DICTIONARY[lang] || I18N_DICTIONARY['en'];
  root.querySelectorAll('[data-i18n]').forEach(function(el) {
    const key = el.getAttribute('data-i18n');
    if (dict && dict[key]) {
      el.textContent = dict[key];
    }
  });

  root.querySelectorAll('[data-i18n-placeholder]').forEach(function(el) {
    const key = el.getAttribute('data-i18n-placeholder');
    if (dict && dict[key]) {
      el.setAttribute('placeholder', dict[key]);
    }
  });
}
window.applyTranslations = applyTranslations;

function initI18n() {
  const savedLang = localStorage.getItem('juzly_lang') || 'en';
  setLanguage(savedLang);
}

function setLanguage(lang) {
  if (!I18N_DICTIONARY[lang]) {
    lang = 'en';
  }
  
  localStorage.setItem('juzly_lang', lang);
  const langConfig = SUPPORTED_LANGS.find(function(l) { return l.code === lang; }) || SUPPORTED_LANGS[0];

  document.documentElement.lang = lang;
  document.documentElement.dir = langConfig.rtl ? 'rtl' : 'ltr';

  if (lang === 'ar' && !document.getElementById('font-noto-arabic')) {
    const link = document.createElement('link');
    link.id = 'font-noto-arabic';
    link.rel = 'stylesheet';
    link.href = 'https://fonts.googleapis.com/css2?family=Noto+Sans+Arabic:wght@400;600;700;800&display=swap';
    document.head.appendChild(link);
  } else if (lang === 'ta' && !document.getElementById('font-noto-tamil')) {
    const link = document.createElement('link');
    link.id = 'font-noto-tamil';
    link.rel = 'stylesheet';
    link.href = 'https://fonts.googleapis.com/css2?family=Noto+Sans+Tamil:wght@400;600;700;800&display=swap';
    document.head.appendChild(link);
  } else if (lang === 'si' && !document.getElementById('font-noto-sinhala')) {
    const link = document.createElement('link');
    link.id = 'font-noto-sinhala';
    link.rel = 'stylesheet';
    link.href = 'https://fonts.googleapis.com/css2?family=Noto+Sans+Sinhala:wght@400;600;700;800&display=swap';
    document.head.appendChild(link);
  }

  const dict = I18N_DICTIONARY[lang] || I18N_DICTIONARY['en'];
  document.querySelectorAll('[data-i18n]').forEach(function(el) {
    const key = el.getAttribute('data-i18n');
    if (dict && dict[key]) {
      el.textContent = dict[key];
    }
  });

  document.querySelectorAll('[data-i18n-placeholder]').forEach(function(el) {
    const key = el.getAttribute('data-i18n-placeholder');
    if (dict && dict[key]) {
      el.setAttribute('placeholder', dict[key]);
    }
  });

  const currentLangLabel = document.getElementById('current-lang-label');
  if (currentLangLabel) {
    currentLangLabel.textContent = langConfig.flag + ' ' + langConfig.code.toUpperCase();
  }

  document.querySelectorAll('.lang-option').forEach(function(opt) {
    if (opt.getAttribute('data-lang') === lang) {
      opt.classList.add('active');
    } else {
      opt.classList.remove('active');
    }
  });

  window.dispatchEvent(new CustomEvent('juzly_lang_change', { detail: { lang: lang, config: langConfig } }));
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', initI18n);
} else {
  initI18n();
}